/* How to fix each rule, in plain words (generated by tests/gen-help.js from tests/help-*.tsv; do not edit). */
EdocHelp.add({
  "BR-DE-1": ["Add at least one cac:PaymentMeans (BG-16 payment instructions) at invoice level.","Aggiungi almeno un cac:PaymentMeans (BG-16 istruzioni di pagamento) a livello di fattura."],
  "BR-DE-10": ["If a delivery address exists (cac:Delivery/cac:DeliveryLocation/cac:Address, BG-15), fill the city (BT-77): cbc:CityName.","Se esiste un indirizzo di consegna (cac:Delivery/cac:DeliveryLocation/cac:Address, BG-15), valorizza la città (BT-77): cbc:CityName."],
  "BR-DE-11": ["If a delivery address exists (cac:Delivery/cac:DeliveryLocation/cac:Address, BG-15), fill the post code (BT-78): cbc:PostalZone.","Se esiste un indirizzo di consegna (cac:Delivery/cac:DeliveryLocation/cac:Address, BG-15), valorizza il CAP (BT-78): cbc:PostalZone."],
  "BR-DE-14": ["Fill the VAT rate (BT-119): cac:TaxCategory/cbc:Percent in every cac:TaxSubtotal, also 0 for zero-rated or exempt.","Valorizza l'aliquota IVA (BT-119): cac:TaxCategory/cbc:Percent in ogni cac:TaxSubtotal, anche 0 per operazioni a aliquota zero o esenti."],
  "BR-DE-15": ["Fill cbc:BuyerReference (BT-10) with a non-empty value. For public buyers this is the Leitweg-ID.","Valorizza cbc:BuyerReference (BT-10) con un valore non vuoto. Per la pubblica amministrazione è la Leitweg-ID."],
  "BR-DE-16": ["If any line, allowance or charge uses VAT category S, Z, E, AE, K, G, L or M, give seller VAT id (BT-31, cac:PartyTaxScheme with VAT), tax number (BT-32) or cac:TaxRepresentativeParty (BG-11).","Se una riga, sconto o maggiorazione usa la categoria IVA S, Z, E, AE, K, G, L o M, indica partita IVA venditore (BT-31, cac:PartyTaxScheme con VAT), codice fiscale/Steuernummer (BT-32) o cac:TaxRepresentativeParty (BG-11)."],
  "BR-DE-17": ["Set cbc:InvoiceTypeCode (BT-3; cbc:CreditNoteTypeCode in a credit note) to one of 326, 380, 381, 384, 389, 875, 876, 877.","Imposta cbc:InvoiceTypeCode (BT-3; cbc:CreditNoteTypeCode in una nota di credito) su uno tra 326, 380, 381, 384, 389, 875, 876, 877."],
  "BR-DE-18": ["Skonto goes in cac:PaymentTerms/cbc:Note (BT-20), one line per tier: #SKONTO#TAGE=n#PROZENT=n.nn# plus optional BASISBETRAG=n#. Uppercase, no extra spaces, line break after the closing #.","Lo Skonto va in cac:PaymentTerms/cbc:Note (BT-20), una riga per livello: #SKONTO#TAGE=n#PROZENT=n.nn# più BASISBETRAG=n# opzionale. Maiuscolo, senza spazi extra, a capo dopo il # finale."],
  "BR-DE-19": ["For payment means code 58 (SEPA credit transfer), the account ID (BT-84, cac:PayeeFinancialAccount/cbc:ID) must be a valid IBAN. Check the IBAN length and check digits.","Per il mezzo di pagamento 58 (bonifico SEPA), l'ID conto (BT-84, cac:PayeeFinancialAccount/cbc:ID) deve essere un IBAN valido. Controlla lunghezza e cifre di controllo."],
  "BR-DE-2": ["Add cac:Contact (BG-6 seller contact) under AccountingSupplierParty/cac:Party with name, telephone and email.","Aggiungi cac:Contact (BG-6 contatto venditore) sotto AccountingSupplierParty/cac:Party con nome, telefono ed email."],
  "BR-DE-20": ["For payment means code 59 (SEPA direct debit), the debited account (BT-91, cac:PaymentMandate/cac:PayerFinancialAccount/cbc:ID) must be a valid IBAN.","Per il mezzo di pagamento 59 (addebito diretto SEPA), il conto da addebitare (BT-91, cac:PaymentMandate/cac:PayerFinancialAccount/cbc:ID) deve essere un IBAN valido."],
  "BR-DE-21": ["Set cbc:CustomizationID (BT-24) to the exact XRechnung identifier, e.g. urn:cen.eu:en16931:2017#compliant#urn:xeinkauf.de:kosit:xrechnung_3.0.","Imposta cbc:CustomizationID (BT-24) sull'identificativo XRechnung esatto, es. urn:cen.eu:en16931:2017#compliant#urn:xeinkauf.de:kosit:xrechnung_3.0."],
  "BR-DE-22": ["Each attachment (cac:AdditionalDocumentReference/cac:Attachment/cbc:EmbeddedDocumentBinaryObject, BT-125) needs a different filename attribute. Rename duplicates.","Ogni allegato (cac:AdditionalDocumentReference/cac:Attachment/cbc:EmbeddedDocumentBinaryObject, BT-125) deve avere un attributo filename diverso. Rinomina i duplicati."],
  "BR-DE-23-a": ["For payment means code 30 or 58 (credit transfer), add cac:PayeeFinancialAccount (BG-17) with the account ID (BT-84, IBAN) in that cac:PaymentMeans.","Per il mezzo di pagamento 30 o 58 (bonifico), aggiungi cac:PayeeFinancialAccount (BG-17) con l'ID conto (BT-84, IBAN) in quel cac:PaymentMeans."],
  "BR-DE-23-b": ["For payment means code 30 or 58 (credit transfer), remove cac:CardAccount (BG-18) and cac:PaymentMandate (BG-19) from that cac:PaymentMeans.","Per il mezzo di pagamento 30 o 58 (bonifico), rimuovi cac:CardAccount (BG-18) e cac:PaymentMandate (BG-19) da quel cac:PaymentMeans."],
  "BR-DE-24-a": ["For payment means code 48, 54 or 55 (card), add cac:CardAccount (BG-18) in that cac:PaymentMeans.","Per il mezzo di pagamento 48, 54 o 55 (carta), aggiungi cac:CardAccount (BG-18) in quel cac:PaymentMeans."],
  "BR-DE-24-b": ["For payment means code 48, 54 or 55 (card), remove cac:PayeeFinancialAccount (BG-17) and cac:PaymentMandate (BG-19) from that cac:PaymentMeans.","Per il mezzo di pagamento 48, 54 o 55 (carta), rimuovi cac:PayeeFinancialAccount (BG-17) e cac:PaymentMandate (BG-19) da quel cac:PaymentMeans."],
  "BR-DE-25-a": ["For payment means code 59 (direct debit), add cac:PaymentMandate (BG-19) in that cac:PaymentMeans.","Per il mezzo di pagamento 59 (addebito diretto), aggiungi cac:PaymentMandate (BG-19) in quel cac:PaymentMeans."],
  "BR-DE-25-b": ["For payment means code 59 (direct debit), remove cac:PayeeFinancialAccount (BG-17) and cac:CardAccount (BG-18) from that cac:PaymentMeans.","Per il mezzo di pagamento 59 (addebito diretto), rimuovi cac:PayeeFinancialAccount (BG-17) e cac:CardAccount (BG-18) da quel cac:PaymentMeans."],
  "BR-DE-26": ["For invoice type code 384 (corrected invoice), add at least one cac:BillingReference/cac:InvoiceDocumentReference (BG-3) with the ID (BT-25) of the invoice being corrected.","Per il tipo documento 384 (fattura rettificativa) aggiungi almeno un cac:BillingReference/cac:InvoiceDocumentReference (BG-3) con l'ID (BT-25) della fattura rettificata."],
  "BR-DE-27": ["Seller contact phone (BT-42, cbc:Telephone) must contain at least three digits.","Il telefono del contatto del venditore (BT-42, cbc:Telephone) deve contenere almeno tre cifre."],
  "BR-DE-28": ["Seller contact email (BT-43, cbc:ElectronicMail) needs exactly one @ with at least two characters on each side, no spaces, and no dot at the start or end.","L'email del contatto del venditore (BT-43, cbc:ElectronicMail) deve avere esattamente una @ con almeno due caratteri per lato, senza spazi e senza punto all'inizio o alla fine."],
  "BR-DE-3": ["Fill the seller city (BT-37): cbc:CityName in the seller cac:PostalAddress.","Valorizza la città del venditore (BT-37): cbc:CityName nel cac:PostalAddress del venditore."],
  "BR-DE-30": ["With direct debit (cac:PaymentMandate, BG-19), add the creditor identifier (BT-90): cac:PartyIdentification/cbc:ID with schemeID=\"SEPA\" in the seller party or cac:PayeeParty.","Con addebito diretto (cac:PaymentMandate, BG-19), aggiungi l'identificativo del creditore (BT-90): cac:PartyIdentification/cbc:ID con schemeID=\"SEPA\" nella parte venditore o in cac:PayeeParty."],
  "BR-DE-31": ["With direct debit (cac:PaymentMandate, BG-19), add the debited account IBAN (BT-91): cac:PaymentMandate/cac:PayerFinancialAccount/cbc:ID.","Con addebito diretto (cac:PaymentMandate, BG-19), aggiungi l'IBAN del conto da addebitare (BT-91): cac:PaymentMandate/cac:PayerFinancialAccount/cbc:ID."],
  "BR-DE-4": ["Fill the seller post code (BT-38): cbc:PostalZone in the seller cac:PostalAddress.","Valorizza il CAP del venditore (BT-38): cbc:PostalZone nel cac:PostalAddress del venditore."],
  "BR-DE-5": ["Fill the seller contact name (BT-41): cbc:Name inside the seller cac:Contact (BG-6).","Valorizza il nome del contatto del venditore (BT-41): cbc:Name dentro cac:Contact (BG-6) del venditore."],
  "BR-DE-6": ["Fill the seller contact phone (BT-42): cbc:Telephone inside the seller cac:Contact (BG-6).","Valorizza il telefono del contatto del venditore (BT-42): cbc:Telephone dentro cac:Contact (BG-6) del venditore."],
  "BR-DE-7": ["Fill the seller contact email (BT-43): cbc:ElectronicMail inside the seller cac:Contact (BG-6).","Valorizza l'email del contatto del venditore (BT-43): cbc:ElectronicMail dentro cac:Contact (BG-6) del venditore."],
  "BR-DE-8": ["Fill the buyer city (BT-52): cbc:CityName in the buyer cac:PostalAddress.","Valorizza la città dell'acquirente (BT-52): cbc:CityName nel cac:PostalAddress dell'acquirente."],
  "BR-DE-9": ["Fill the buyer post code (BT-53): cbc:PostalZone in the buyer cac:PostalAddress.","Valorizza il CAP dell'acquirente (BT-53): cbc:PostalZone nel cac:PostalAddress dell'acquirente."],
  "BR-DE-CVD-01": ["CVD profile only: fill the contract reference (BT-12): cac:ContractDocumentReference/cbc:ID.","Solo profilo CVD: valorizza il riferimento al contratto (BT-12): cac:ContractDocumentReference/cbc:ID."],
  "BR-DE-CVD-02": ["CVD profile only: fill the tender or lot reference (BT-17): cac:OriginatorDocumentReference/cbc:ID.","Solo profilo CVD: valorizza il riferimento a gara o lotto (BT-17): cac:OriginatorDocumentReference/cbc:ID."],
  "BR-DE-CVD-03": ["CVD profile only: at least one line item needs cbc:ItemClassificationCode (BT-158) with listID=\"CVD\" and a cac:AdditionalItemProperty (BG-32) with cbc:Name (BT-160) \"cva\".","Solo profilo CVD: almeno una riga deve avere cbc:ItemClassificationCode (BT-158) con listID=\"CVD\" e un cac:AdditionalItemProperty (BG-32) con cbc:Name (BT-160) \"cva\"."],
  "BR-DE-CVD-04": ["CVD profile only: if listID=\"CVD\", the value of cbc:ItemClassificationCode (BT-158) must be an allowed vehicle category from the CVD list.","Solo profilo CVD: se listID=\"CVD\", il valore di cbc:ItemClassificationCode (BT-158) deve essere una categoria di veicolo ammessa dalla lista CVD."],
  "BR-DE-CVD-05": ["CVD profile only: when cbc:Name (BT-160) is \"cva\", cbc:Value (BT-161) must be one of the allowed CVA codes.","Solo profilo CVD: quando cbc:Name (BT-160) è \"cva\", cbc:Value (BT-161) deve essere uno dei codici CVA ammessi."],
  "BR-DE-CVD-06-a": ["CVD profile only: a line with ItemClassificationCode listID=\"CVD\" (BT-158) needs exactly one cac:AdditionalItemProperty with cbc:Name (BT-160) \"cva\".","Solo profilo CVD: una riga con ItemClassificationCode listID=\"CVD\" (BT-158) deve avere esattamente un cac:AdditionalItemProperty con cbc:Name (BT-160) \"cva\"."],
  "BR-DE-CVD-06-b": ["CVD profile only: a line with AdditionalItemProperty cbc:Name (BT-160) \"cva\" needs exactly one ItemClassificationCode (BT-158) with listID=\"CVD\".","Solo profilo CVD: una riga con AdditionalItemProperty cbc:Name (BT-160) \"cva\" deve avere esattamente un ItemClassificationCode (BT-158) con listID=\"CVD\"."],
  "BR-DE-TMP-32": ["State the delivery/service date in one of: cac:Delivery/cbc:ActualDeliveryDate (BT-72), invoice cac:InvoicePeriod (BG-14), or a cac:InvoicePeriod (BG-26) in every line.","Indica la data di consegna/prestazione in uno di: cac:Delivery/cbc:ActualDeliveryDate (BT-72), cac:InvoicePeriod di fattura (BG-14), oppure cac:InvoicePeriod (BG-26) in ogni riga."],
  "BR-DEX-01": ["Extension only: the attachment cbc:EmbeddedDocumentBinaryObject (BT-125) mimeCode must be application/pdf, image/png, image/jpeg, text/csv, xlsx, ods or application/xml.","Solo Extension: il mimeCode dell'allegato cbc:EmbeddedDocumentBinaryObject (BT-125) deve essere application/pdf, image/png, image/jpeg, text/csv, xlsx, ods o application/xml."],
  "BR-DEX-02": ["Extension only: a line (BG-25) or sub line (BG-DEX-01) that has cac:SubInvoiceLine must have cbc:LineExtensionAmount (BT-131) equal to the sum of its direct sub lines' amounts.","Solo Extension: una riga (BG-25) o sottoriga (BG-DEX-01) con cac:SubInvoiceLine deve avere cbc:LineExtensionAmount (BT-131) pari alla somma degli importi delle sottorighe dirette."],
  "BR-DEX-03": ["Extension only: each cac:SubInvoiceLine (BG-DEX-01) needs exactly one cac:Item/cac:ClassifiedTaxCategory (BG-DEX-06).","Solo Extension: ogni cac:SubInvoiceLine (BG-DEX-01) deve avere esattamente un cac:Item/cac:ClassifiedTaxCategory (BG-DEX-06)."],
  "BR-DEX-04": ["Extension only: schemeID on a party cac:PartyIdentification/cbc:ID must be one ISO 6523 ICD code. SEPA is also allowed for the seller or payee.","Solo Extension: lo schemeID di cac:PartyIdentification/cbc:ID deve essere un codice ISO 6523 ICD. SEPA è ammesso anche per venditore o beneficiario."],
  "BR-DEX-05": ["Extension only: schemeID on cac:PartyLegalEntity/cbc:CompanyID must be one code from the ISO 6523 ICD list.","Solo Extension: lo schemeID di cac:PartyLegalEntity/cbc:CompanyID deve essere un codice della lista ISO 6523 ICD."],
  "BR-DEX-06": ["Extension only: schemeID on cac:StandardItemIdentification/cbc:ID must be one code from the ISO 6523 ICD list.","Solo Extension: lo schemeID di cac:StandardItemIdentification/cbc:ID deve essere un codice della lista ISO 6523 ICD."],
  "BR-DEX-07": ["Extension only: schemeID on cbc:EndpointID (BT-34/BT-49) must be one code from the CEF EAS list.","Solo Extension: lo schemeID di cbc:EndpointID (BT-34/BT-49) deve essere un codice della lista CEF EAS."],
  "BR-DEX-08": ["Extension only: schemeID on cac:DeliveryLocation/cbc:ID (BT-71) must be one code from the ISO 6523 ICD list.","Solo Extension: lo schemeID di cac:DeliveryLocation/cbc:ID (BT-71) deve essere un codice della lista ISO 6523 ICD."],
  "BR-DEX-09": ["Extension only: PayableAmount (BT-115) = TaxInclusiveAmount (BT-112) - PrepaidAmount (BT-113) + PayableRoundingAmount (BT-114) + third party payments (BT-DEX-002). Fix the totals.","Solo Extension: PayableAmount (BT-115) = TaxInclusiveAmount (BT-112) - PrepaidAmount (BT-113) + PayableRoundingAmount (BT-114) + pagamenti di terzi (BT-DEX-002). Correggi i totali."],
  "BR-DEX-10": ["Extension only: each cac:PrepaidPayment (BG-DEX-09) needs cbc:ID (BT-DEX-001, payment type) with a value.","Solo Extension: ogni cac:PrepaidPayment (BG-DEX-09) deve avere cbc:ID (BT-DEX-001, tipo di pagamento) valorizzato."],
  "BR-DEX-11": ["Extension only: each cac:PrepaidPayment (BG-DEX-09) needs cbc:PaidAmount (BT-DEX-002) with a value.","Solo Extension: ogni cac:PrepaidPayment (BG-DEX-09) deve avere cbc:PaidAmount (BT-DEX-002) valorizzato."],
  "BR-DEX-12": ["Extension only: each cac:PrepaidPayment (BG-DEX-09) needs cbc:InstructionID (BT-DEX-003, description) with a value.","Solo Extension: ogni cac:PrepaidPayment (BG-DEX-09) deve avere cbc:InstructionID (BT-DEX-003, descrizione) valorizzato."],
  "BR-DEX-13": ["Extension only: cbc:PaidAmount (BT-DEX-002) in cac:PrepaidPayment may have at most 2 decimal places.","Solo Extension: cbc:PaidAmount (BT-DEX-002) in cac:PrepaidPayment può avere al massimo 2 decimali."],
  "BR-DEX-14": ["Extension only: the currencyID of cac:PrepaidPayment/cbc:PaidAmount (BT-DEX-002) must equal cbc:DocumentCurrencyCode (BT-5).","Solo Extension: il currencyID di cac:PrepaidPayment/cbc:PaidAmount (BT-DEX-002) deve essere uguale a cbc:DocumentCurrencyCode (BT-5)."],
  "BR-TMP-2": ["Put a full absolute URL with scheme (e.g. https://...) in cac:ExternalReference/cbc:URI (BT-124).","Inserisci un URL assoluto completo con schema (es. https://...) in cac:ExternalReference/cbc:URI (BT-124)."],
  "BR-TMP-6": ["Write every date element (IssueDate, DueDate, StartDate, EndDate, ActualDeliveryDate, TaxPointDate, PaymentDueDate) as YYYY-MM-DD only, no time or timezone.","Scrivi ogni data (IssueDate, DueDate, StartDate, EndDate, ActualDeliveryDate, TaxPointDate, PaymentDueDate) solo come AAAA-MM-GG (YYYY-MM-DD), senza ora né fuso."],
  "BR-TMP-CVD-01": ["CVD profile only: the listID of cbc:ItemClassificationCode (BT-158) must be a code from the UNTDID 7143 list (plus CVD).","Solo profilo CVD: il listID di cbc:ItemClassificationCode (BT-158) deve essere un codice della lista UNTDID 7143 (più CVD)."],
  "PEPPOL-EN16931-R001": ["Add cbc:ProfileID (BT-23, business process) at the top level of the invoice, e.g. urn:fdc:peppol.eu:2017:poacc:billing:01:1.0.","Aggiungi cbc:ProfileID (BT-23, processo di business) a livello principale della fattura, es. urn:fdc:peppol.eu:2017:poacc:billing:01:1.0."],
  "PEPPOL-EN16931-R005": ["If cbc:TaxCurrencyCode (BT-6) is sent, use a currency different from cbc:DocumentCurrencyCode (BT-5). If they are the same, remove BT-6.","Se invii cbc:TaxCurrencyCode (BT-6), usa una valuta diversa da cbc:DocumentCurrencyCode (BT-5). Se sono uguali, rimuovi BT-6."],
  "PEPPOL-EN16931-R008": ["Remove every empty element or give it a value. No tag may be empty or contain only spaces.","Rimuovi ogni elemento vuoto oppure valorizzalo. Nessun tag può essere vuoto o contenere solo spazi."],
  "PEPPOL-EN16931-R010": ["Add the buyer electronic address (BT-49): cbc:EndpointID with schemeID under AccountingCustomerParty/cac:Party.","Aggiungi l'indirizzo elettronico dell'acquirente (BT-49): cbc:EndpointID con schemeID sotto AccountingCustomerParty/cac:Party."],
  "PEPPOL-EN16931-R020": ["Add the seller electronic address (BT-34): cbc:EndpointID with schemeID under AccountingSupplierParty/cac:Party.","Aggiungi l'indirizzo elettronico del venditore (BT-34): cbc:EndpointID con schemeID sotto AccountingSupplierParty/cac:Party."],
  "PEPPOL-EN16931-R040": ["When both cbc:BaseAmount and cbc:MultiplierFactorNumeric are given, cbc:Amount must equal BaseAmount x percentage / 100. Correct one of the three values.","Quando sono presenti sia cbc:BaseAmount sia cbc:MultiplierFactorNumeric, cbc:Amount deve essere BaseAmount x percentuale / 100. Correggi uno dei tre valori."],
  "PEPPOL-EN16931-R041": ["On a document or line allowance/charge (BG-20/BG-21/BG-27/BG-28) that has cbc:MultiplierFactorNumeric (percentage), also add cbc:BaseAmount, or remove the percentage.","In uno sconto/maggiorazione di documento o riga (BG-20/BG-21/BG-27/BG-28) con cbc:MultiplierFactorNumeric (percentuale), aggiungi anche cbc:BaseAmount, oppure rimuovi la percentuale."],
  "PEPPOL-EN16931-R042": ["On a document or line allowance/charge that has cbc:BaseAmount, also add cbc:MultiplierFactorNumeric (percentage), or remove the base amount.","In uno sconto/maggiorazione di documento o riga con cbc:BaseAmount, aggiungi anche cbc:MultiplierFactorNumeric (percentuale), oppure rimuovi l'importo base."],
  "PEPPOL-EN16931-R043": ["Set cbc:ChargeIndicator on every cac:AllowanceCharge to exactly true (charge) or false (allowance), lowercase.","Imposta cbc:ChargeIndicator in ogni cac:AllowanceCharge esattamente su true (maggiorazione) o false (sconto), in minuscolo."],
  "PEPPOL-EN16931-R044": ["In cac:Price/cac:AllowanceCharge (price discount BG-29) set cbc:ChargeIndicator to false. Price charges are not allowed.","In cac:Price/cac:AllowanceCharge (sconto sul prezzo BG-29) imposta cbc:ChargeIndicator su false. Le maggiorazioni sul prezzo non sono ammesse."],
  "PEPPOL-EN16931-R046": ["With gross price (BT-148, cac:Price/cac:AllowanceCharge/cbc:BaseAmount): net price cbc:PriceAmount (BT-146) = gross price - price discount cbc:Amount (BT-147). Fix one of them.","Con prezzo lordo (BT-148, cac:Price/cac:AllowanceCharge/cbc:BaseAmount): prezzo netto cbc:PriceAmount (BT-146) = prezzo lordo - sconto sul prezzo cbc:Amount (BT-147). Correggi uno dei valori."],
  "PEPPOL-EN16931-R053": ["Use exactly one cac:TaxTotal that contains cac:TaxSubtotal (VAT breakdown BG-23). Put all VAT categories as subtotals inside that one TaxTotal.","Usa esattamente un cac:TaxTotal che contiene cac:TaxSubtotal (dettaglio IVA BG-23). Metti tutte le categorie IVA come subtotali in quell'unico TaxTotal."],
  "PEPPOL-EN16931-R054": ["If cbc:TaxCurrencyCode (BT-6) is present, add one extra cac:TaxTotal with only cbc:TaxAmount (BT-111, in that currency) and no TaxSubtotal. If BT-6 is absent, do not add it.","Se cbc:TaxCurrencyCode (BT-6) è presente, aggiungi un cac:TaxTotal extra con solo cbc:TaxAmount (BT-111, in quella valuta) e senza TaxSubtotal. Se BT-6 manca, non aggiungerlo."],
  "PEPPOL-EN16931-R055": ["With cbc:TaxCurrencyCode (BT-6), the two cac:TaxTotal/cbc:TaxAmount (BT-110 in invoice currency, BT-111 in VAT currency) must both be negative or zero, or both positive or zero.","Con cbc:TaxCurrencyCode (BT-6), i due cac:TaxTotal/cbc:TaxAmount (BT-110 in valuta fattura, BT-111 in valuta IVA) devono essere entrambi negativi o zero, oppure entrambi positivi o zero."],
  "PEPPOL-EN16931-R061": ["For payment means code 49 or 59 (direct debit) add cac:PaymentMandate/cbc:ID, the mandate reference (BT-89).","Per codice mezzo di pagamento 49 o 59 (addebito diretto) aggiungi cac:PaymentMandate/cbc:ID, il riferimento del mandato (BT-89)."],
  "PEPPOL-EN16931-R101": ["In a line, cac:DocumentReference may only be used with cbc:DocumentTypeCode 130 (invoiced object identifier, BT-18/BT-128). Set the code to 130 or remove the element.","In una riga, cac:DocumentReference è ammesso solo con cbc:DocumentTypeCode 130 (identificativo oggetto fatturato, BT-18/BT-128). Imposta il codice 130 o rimuovi l'elemento."],
  "PEPPOL-EN16931-R110": ["If the invoice has an invoice period start date (BT-73), each line period start date (BT-134, cac:InvoiceLine/cac:InvoicePeriod/cbc:StartDate) must not be earlier than it.","Se la fattura ha una data di inizio periodo (BT-73), la data di inizio periodo di ogni riga (BT-134, cac:InvoiceLine/cac:InvoicePeriod/cbc:StartDate) non deve essere precedente."],
  "PEPPOL-EN16931-R111": ["If the invoice has an invoice period end date (BT-74), each line period end date (BT-135, cac:InvoiceLine/cac:InvoicePeriod/cbc:EndDate) must not be later than it.","Se la fattura ha una data di fine periodo (BT-74), la data di fine periodo di ogni riga (BT-135, cac:InvoiceLine/cac:InvoicePeriod/cbc:EndDate) non deve essere successiva."],
  "PEPPOL-EN16931-R120": ["Line net amount (BT-131, cbc:LineExtensionAmount) = quantity x (price BT-146 / base quantity) + line charges - line allowances. Recalculate and fix the amount or the inputs.","Importo netto riga (BT-131, cbc:LineExtensionAmount) = quantità x (prezzo BT-146 / quantità base) + maggiorazioni riga - sconti riga. Ricalcola e correggi importo o dati di partenza."],
  "PEPPOL-EN16931-R121": ["If cac:Price/cbc:BaseQuantity (BT-149) is present, it must be greater than 0. Fix the value or remove the element.","Se cac:Price/cbc:BaseQuantity (BT-149) è presente, deve essere maggiore di 0. Correggi il valore o rimuovi l'elemento."],
  "PEPPOL-EN16931-R130": ["Set the unitCode of cac:Price/cbc:BaseQuantity (BT-150) equal to the unitCode of the line quantity (BT-130, cbc:InvoicedQuantity).","Imposta lo unitCode di cac:Price/cbc:BaseQuantity (BT-150) uguale allo unitCode della quantità di riga (BT-130, cbc:InvoicedQuantity)."]
});
